export interface ColorScheme {
  name: string;
  colors: string[];
}

export interface WheelConfig {
  items: string[];
  colorScheme: ColorScheme;
  borderWidth: number;
  borderColor: string;
  hubRadius: number;
  hubColor: string;
  fontSize: number;
  fontFamily: string;
  fontWeight: string;
  fontColor: string;
  rotation: number;
  showText: boolean;
}

import { ColorScheme, WheelConfig } from './types';

export const COLOR_SCHEMES: ColorScheme[] = [
  {
    name: 'Rainbow',
    colors: ['#ff9999', '#ffff99', '#99ff99', '#99ffff', '#9999ff', '#ff99ff']
  },
  {
    name: 'Modern Pastels',
    colors: ['#F3E5F5', '#E8EAF6', '#E3F2FD', '#E0F2F1', '#F1F8E9', '#FFFDE7']
  },
