    colors: ['#0D47A1', '#1565C0', '#1976D2', '#1E88E5', '#2196F3', '#42A5F5']
  }
];

export const DEFAULT_CONFIG: WheelConfig = {
  items: ['Manchester', 'Paris', 'London', 'Dubai', 'Singapore', 'New York', 'Kuala Lumpur', 'Tokyo', 'Istanbul', 'Seoul', 'Hong Kong', 'Barcelona', 'Amsterdam', 'Milan', 'Taipei'],
  colorScheme: COLOR_SCHEMES[0],
  borderWidth: 15,
  borderColor: '#333333',
  hubRadius: 40,
  hubColor: '#FFFFFF',
  fontSize: 18,
  fontFamily: 'system-ui, sans-serif',
  fontWeight: 'bold',
  fontColor: '#333333',
  rotation: 0,
  showText: true
};

import React, { useEffect, useRef } from 'react';
import { WheelConfig } from '../types';

interface WheelCanvasProps {
  config: WheelConfig;
  exportScale?: number;
  onCanvasReady?: (canvas: HTMLCanvasElement) => void;
}

export const WheelCanvas: React.FC<WheelCanvasProps> = ({ config, exportScale = 2, onCanvasReady }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const drawWheel = (canvas: HTMLCanvasElement, scale: number) => {
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const size = canvas.width;
    const center = size / 2;
    const radius = center - (config.borderWidth * scale);
    const { items, colorScheme, borderWidth, borderColor, hubRadius, hubColor, fontSize, fontFamily, fontWeight, fontColor } = config;

    // Clear canvas for transparency
    ctx.clearRect(0, 0, size, size);

    if (items.length === 0) return;

    const sliceAngle = (2 * Math.PI) / items.length;

    // 1. Draw Slices
    items.forEach((item, i) => {
      const startAngle = i * sliceAngle + (config.rotation * Math.PI / 180);
      const endAngle = startAngle + sliceAngle;

      // Draw path
      ctx.beginPath();
      ctx.moveTo(center, center);
      ctx.arc(center, center, radius, startAngle, endAngle);
      ctx.closePath();

      // Fill
      ctx.fillStyle = colorScheme.colors[i % colorScheme.colors.length];
      ctx.fill();

      // Stroke between slices (optional, for cleaner looks)
      ctx.lineWidth = 1 * scale;
      ctx.strokeStyle = 'rgba(0,0,0,0.1)';
      ctx.stroke();

      // 2. Draw Text
      if (config.showText) {
        ctx.save();
        ctx.translate(center, center);
        ctx.rotate(startAngle + sliceAngle / 2);

        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = fontColor;
        ctx.font = `${fontWeight} ${fontSize * scale}px ${fontFamily}`;

        // Add some padding from the edge
        const textRadius = radius - (10 * scale);
        ctx.fillText(item, textRadius, 0);

        ctx.restore();
      }
    });

    // 3. Outer Border (Rim)
    if (borderWidth > 0) {
      ctx.beginPath();
      ctx.arc(center, center, radius + (borderWidth * scale / 2), 0, 2 * Math.PI);
      ctx.lineWidth = borderWidth * scale;
      ctx.strokeStyle = borderColor;
      ctx.stroke();
    }

    // 4. Center Hub
    if (hubRadius > 0) {
      ctx.beginPath();
      ctx.arc(center, center, hubRadius * scale, 0, 2 * Math.PI);
      ctx.fillStyle = hubColor;
      ctx.fill();
      // Hub stroke
      ctx.lineWidth = 2 * scale;
      ctx.strokeStyle = borderColor;
      ctx.stroke();
    }
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const scale = exportScale;
    const displaySize = 800; // Fixed display size
    canvas.width = displaySize * scale;
    canvas.height = displaySize * scale;
    canvas.style.width = `${displaySize}px`;
    canvas.style.height = `${displaySize}px`;

    drawWheel(canvas, scale);
    if (onCanvasReady) onCanvasReady(canvas);
  }, [config, exportScale]);

  return (
    <div className="flex justify-center items-center bg-transparent p-4 overflow-auto min-h-full">
      <canvas 
        ref={canvasRef} 
        className="max-w-full h-auto drop-shadow-2xl"
      />
    </div>
  );
};

import React, { useState, useCallback, useRef } from 'react';
import { WheelCanvas } from './components/WheelCanvas';
import { COLOR_SCHEMES, DEFAULT_CONFIG } from './constants';
import { WheelConfig, ColorScheme } from './types';

const App: React.FC = () => {
  const [config, setConfig] = useState<WheelConfig>(DEFAULT_CONFIG);
  const [textInput, setTextInput] = useState(DEFAULT_CONFIG.items.join('\n'));
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setTextInput(value);
    const items = value.split('\n').filter(line => line.trim() !== '');
    setConfig(prev => ({ ...prev, items }));
  };

  const updateConfig = (updates: Partial<WheelConfig>) => {
    setConfig(prev => ({ ...prev, ...updates }));
  };

  const downloadImage = () => {
    if (!canvasRef.current) return;

    // For high-quality export, we use a larger scale
    // Create a temporary canvas for UHD export
    const exportScale = 4; // 4x scale for UHD
    const tempCanvas = document.createElement('canvas');
    const size = 800 * exportScale;
    tempCanvas.width = size;
    tempCanvas.height = size;

    // Since our WheelCanvas already draws to its ref, we can trigger a high-quality redraw 
    // or just use the current canvas if it's already high enough.
    // In this implementation, the display canvas is already 2x (1600px).
    // Let's just download the current one to be simple, but let's make it 4x for "Ultra HD".

    // We'll simulate a redraw by creating a hidden WheelCanvas or just manual draw
    const link = document.createElement('a');
    link.download = `wheel-${Date.now()}.png`;
    link.href = canvasRef.current.toDataURL('image/png', 1.0);
    link.click();
  };

  return (
    <div className="flex flex-col md:flex-row h-screen overflow-hidden bg-slate-50">
      {/* Sidebar Controls */}
      <div className="w-full md:w-96 bg-white border-r border-slate-200 overflow-y-auto p-6 flex flex-col gap-6 shadow-sm z-10">
        <header>
          <h1 className="text-2xl font-bold text-slate-800">Wheel Generator</h1>
          <p className="text-sm text-slate-500">Create high-definition custom wheels</p>
        </header>

        {/* Text Input */}
        <section>
          <label className="block text-sm font-semibold text-slate-700 mb-2">Wheel Items (one per line)</label>
          <textarea
            className="w-full h-48 p-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none font-mono text-sm resize-none"
            value={textInput}
            onChange={handleTextChange}
            placeholder="Type items here..."
          />
        </section>

        {/* Styling Options */}
        <section className="space-y-4">
          <h2 className="text-sm font-bold text-slate-800 uppercase tracking-wider">Appearance</h2>

          {/* Color Schemes */}
          <div>
            <label className="block text-xs font-semibold text-slate-500 mb-2">Color Scheme</label>
            <div className="grid grid-cols-1 gap-2">
              {COLOR_SCHEMES.map(scheme => (
                <button
                  key={scheme.name}
                  onClick={() => updateConfig({ colorScheme: scheme })}
                  className={`flex items-center gap-2 p-2 rounded-md border transition-all ${
                    config.colorScheme.name === scheme.name ? 'border-blue-500 bg-blue-50' : 'border-slate-200 hover:bg-slate-50'
                  }`}
                >
                  <div className="flex flex-1 h-4 rounded overflow-hidden">
                    {scheme.colors.slice(0, 6).map((c, i) => (
                      <div key={i} className="flex-1" style={{ backgroundColor: c }} />
                    ))}
                  </div>
                  <span className="text-xs font-medium text-slate-700">{scheme.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-500 mb-1">Border Width</label>
              <input
                type="number"
                min="0"
                max="50"
                value={config.borderWidth}
                onChange={(e) => updateConfig({ borderWidth: Number(e.target.value) })}
