            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-500 mb-1">Border Color</label>
              <div className="flex gap-2">
                <input
                  type="color"
                  value={config.borderColor}
                  onChange={(e) => updateConfig({ borderColor: e.target.value })}
                  className="w-10 h-10 border-none p-0 cursor-pointer rounded overflow-hidden"
                />
                <input 
                  type="text" 
                  value={config.borderColor} 
                  onChange={(e) => updateConfig({ borderColor: e.target.value })}
                  className="flex-1 w-0 text-xs p-2 border border-slate-300 rounded uppercase"
                />
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-500 mb-1">Hub Radius</label>
              <input
                type="number"
                min="0"
                max="100"
                value={config.hubRadius}
                onChange={(e) => updateConfig({ hubRadius: Number(e.target.value) })}
                className="w-full p-2 border border-slate-300 rounded-md text-sm"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-500 mb-1">Hub Color</label>
              <div className="flex gap-2">
                <input
                  type="color"
                  value={config.hubColor}
                  onChange={(e) => updateConfig({ hubColor: e.target.value })}
                  className="w-10 h-10 border-none p-0 cursor-pointer rounded overflow-hidden"
                />
                 <input 
                  type="text" 
                  value={config.hubColor} 
                  onChange={(e) => updateConfig({ hubColor: e.target.value })}
                  className="flex-1 w-0 text-xs p-2 border border-slate-300 rounded uppercase"
                />
              </div>
            </div>
          </div>
        </section>

        <section className="space-y-4">
          <h2 className="text-sm font-bold text-slate-800 uppercase tracking-wider">Typography</h2>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-500 mb-1">Font Size</label>
              <input
                type="number"
                min="8"
                max="60"
                value={config.fontSize}
                onChange={(e) => updateConfig({ fontSize: Number(e.target.value) })}
                className="w-full p-2 border border-slate-300 rounded-md text-sm"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-500 mb-1">Font Weight</label>
              <select
                value={config.fontWeight}
                onChange={(e) => updateConfig({ fontWeight: e.target.value })}
                className="w-full p-2 border border-slate-300 rounded-md text-sm"
              >
                <option value="normal">Normal</option>
                <option value="medium">Medium</option>
                <option value="bold">Bold</option>
                <option value="900">Heavy</option>
              </select>
            </div>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-500 mb-1">Font Color</label>
            <div className="flex gap-2">
              <input
                type="color"
                value={config.fontColor}
                onChange={(e) => updateConfig({ fontColor: e.target.value })}
                className="w-10 h-10 border-none p-0 cursor-pointer rounded overflow-hidden"
              />
              <input 
                type="text" 
                value={config.fontColor} 
                onChange={(e) => updateConfig({ fontColor: e.target.value })}
                className="flex-1 w-0 text-xs p-2 border border-slate-300 rounded uppercase"
              />
            </div>
          </div>
        </section>

        {/* Action Button */}
        <button
          onClick={downloadImage}
          className="mt-auto w-full py-4 px-6 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl shadow-lg shadow-blue-200 transition-all flex items-center justify-center gap-2"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
          </svg>
          Download PNG (UHD)
        </button>
      </div>

      {/* Preview Area */}
      <main className="flex-1 bg-slate-100 flex items-center justify-center relative overflow-hidden pattern-dots">
        <div className="absolute inset-0 opacity-10 pointer-events-none" style={{ backgroundImage: 'radial-gradient(#000 0.5px, transparent 0.5px)', backgroundSize: '20px 20px' }} />

        <div className="relative w-full h-full flex items-center justify-center p-8">
          <WheelCanvas 
            config={config} 
            exportScale={3} // Higher resolution for better preview and initial export
            onCanvasReady={(canvas) => { canvasRef.current = canvas; }} 
          />
        </div>

        {/* Legend / Info Overlay */}
        <div className="absolute bottom-6 right-6 bg-white/80 backdrop-blur p-3 rounded-lg border border-slate-200 shadow-sm text-xs text-slate-600">
          <p>Resolution: 2400 × 2400 pixels</p>
          <p>Format: PNG (Transparent)</p>
          <p>Scale: 3.0x Supersampling</p>
        </div>
      </main>
    </div>
  );
};

export default App;

export interface ColorScheme {
  name: string;
  colors: string[];
}

