export const DEFAULT_CONFIG: WheelConfig = {
  items: ['Manchester', 'Paris', 'London', 'Dubai', 'Singapore', 'New York', 'Kuala Lumpur', 'Tokyo', 'Istanbul', 'Seoul', 'Hong Kong', 'Barcelona', 'Amsterdam', 'Milan', 'Taipei'],
