import React, { useEffect, useRef } from 'react';
import { WheelConfig } from '../types';

interface WheelCanvasProps {
  config: WheelConfig;
  exportScale?: number;
  onCanvasReady?: (canvas: HTMLCanvasElement) => void;
}

export const WheelCanvas: React.FC<WheelCanvasProps> = ({ config, exportScale = 2, onCanvasReady }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const drawWheel = (canvas: HTMLCanvasElement, scale: number) => {
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const size = canvas.width;
    const center = size / 2;
    // Ensure the entire wheel including border is visible by calculating max radius carefully
    const outerRadius = (size / 2) - (4 * scale); // 4px safe margin
    const radius = outerRadius - (config.borderWidth * scale);

    const { items, colorScheme, borderWidth, borderColor, borderStyle, hubRadius, hubColor, fontSize, fontFamily, fontWeight, fontColor } = config;

    ctx.clearRect(0, 0, size, size);
    if (items.length === 0) return;

    const sliceAngle = (2 * Math.PI) / items.length;

    // 1. Draw Slices
    items.forEach((item, i) => {
      const startAngle = i * sliceAngle + (config.rotation * Math.PI / 180);
      const endAngle = startAngle + sliceAngle;

      ctx.beginPath();
      ctx.moveTo(center, center);
      ctx.arc(center, center, radius, startAngle, endAngle);
      ctx.closePath();

      ctx.fillStyle = colorScheme.colors[i % colorScheme.colors.length];
      ctx.fill();

      ctx.lineWidth = 1 * scale;
      ctx.strokeStyle = 'rgba(0,0,0,0.05)';
      ctx.stroke();

      if (config.showText) {
        ctx.save();
        ctx.translate(center, center);
        ctx.rotate(startAngle + sliceAngle / 2);

        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillStyle = fontColor;
        ctx.font = `${fontWeight} ${fontSize * scale}px ${fontFamily}`;

        const textRadius = radius - (12 * scale);
        // Truncate text if it's too long for the segment
        const maxWidth = radius * 0.8;
        ctx.fillText(item, textRadius, 0, maxWidth);

        ctx.restore();
      }
    });

    // 2. Outer Border (Rim) with Texture
    if (borderWidth > 0) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(center, center, radius + (borderWidth * scale / 2), 0, 2 * Math.PI);
      ctx.lineWidth = borderWidth * scale;

      if (borderStyle === 'metallic') {
        const grad = ctx.createLinearGradient(center - outerRadius, center - outerRadius, center + outerRadius, center + outerRadius);
        grad.addColorStop(0, '#555');
        grad.addColorStop(0.2, '#fff');
        grad.addColorStop(0.4, '#888');
        grad.addColorStop(0.6, '#fff');
        grad.addColorStop(0.8, '#555');
        grad.addColorStop(1, '#aaa');
        ctx.strokeStyle = grad;
      } else if (borderStyle === 'glossy') {
        const grad = ctx.createRadialGradient(center, center, radius, center, center, outerRadius);
        grad.addColorStop(0, borderColor);
        grad.addColorStop(0.5, '#fff');
        grad.addColorStop(1, borderColor);
        ctx.strokeStyle = grad;
      } else if (borderStyle === 'dotted') {
        ctx.strokeStyle = borderColor;
        ctx.setLineDash([5 * scale, 10 * scale]);
      } else {
        ctx.strokeStyle = borderColor;
      }

      ctx.stroke();
      ctx.restore();
    }

    // 3. Center Hub
    if (hubRadius > 0) {
      ctx.beginPath();
      ctx.arc(center, center, hubRadius * scale, 0, 2 * Math.PI);

      if (borderStyle === 'metallic' || borderStyle === 'glossy') {
         const hubGrad = ctx.createRadialGradient(center - hubRadius/2, center - hubRadius/2, 0, center, center, hubRadius * scale);
         hubGrad.addColorStop(0, '#fff');
         hubGrad.addColorStop(1, hubColor);
         ctx.fillStyle = hubGrad;
      } else {
        ctx.fillStyle = hubColor;
      }

      ctx.fill();
      ctx.lineWidth = 2 * scale;
      ctx.strokeStyle = borderColor;
      ctx.stroke();
    }
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const scale = exportScale;
    const displaySize = 800;
    canvas.width = displaySize * scale;
    canvas.height = displaySize * scale;
    // Set display size to 100% of parent for 1:1 visibility
    canvas.style.width = `100%`;
    canvas.style.height = `100%`;

    drawWheel(canvas, scale);
    if (onCanvasReady) onCanvasReady(canvas);
  }, [config, exportScale]);

  return (
    <div className="w-full h-full flex justify-center items-center bg-transparent p-0 overflow-hidden">
      <canvas 
        ref={canvasRef} 
        className="max-w-full max-h-full object-contain drop-shadow-[0_20px_50px_rgba(0,0,0,0.5)]"
      />
    </div>
  );
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { WheelCanvas } from './components/WheelCanvas';
import { COLOR_SCHEMES, DEFAULT_CONFIG, CHINESE_FONTS } from './constants';
import { WheelConfig, ColorScheme, BorderStyle } from './types';
import { GoogleGenAI } from "@google/genai";

const App: React.FC = () => {
  const [config, setConfig] = useState<WheelConfig>(DEFAULT_CONFIG);
  const [textInput, setTextInput] = useState(DEFAULT_CONFIG.items.join('\n'));
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<{ role: 'user' | 'ai', content: string, items?: string[] }[]>([
    { role: 'ai', content: '您好！我是您的灵感助手。您想要设置多少个格子？或者有什么特定的主题（比如：下午茶吃什么、年会奖项、旅游城市等）？' }
  ]);
  const [isAiLoading, setIsAiLoading] = useState(false);

  const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setTextInput(value);
    const items = value.split('\n').filter(line => line.trim() !== '');
    setConfig(prev => ({ ...prev, items }));
  };

  const updateConfig = (updates: Partial<WheelConfig>) => {
    setConfig(prev => ({ ...prev, ...updates }));
  };

  const downloadImage = () => {
    if (!canvasRef.current) return;
    const link = document.createElement('a');
    link.download = `wheel-hd-${Date.now()}.png`;
    link.href = canvasRef.current.toDataURL('image/png', 1.0);
    link.click();
  };

  const callAi = async () => {
    if (!chatInput.trim() || isAiLoading) return;
    const userMsg = chatInput;
    setChatInput('');
    setChatHistory(prev => [...prev, { role: 'user', content: userMsg }]);
    setIsAiLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `用户需求: ${userMsg}. 
        请根据需求生成一套适合转盘的文案列表。
        要求：
        1. 返回一段亲切的对话回复。
        2. 返回一个纯文本格式的列表，每行一个项目。
        3. 尽可能提供5-15个选项。`,
        config: {
          systemInstruction: "你是一个创意转盘助手。帮助用户生成转盘内容。你需要输出友好的建议，并提供一个可以被一键应用的列表。列表项应该简洁有力。"
        }
      });

      const aiText = response.text || '';
      const lines = aiText.split('\n');
      const detectedItems = lines
        .map(l => l.replace(/^[-*•\d.]+\s*/, '').trim())
        .filter(l => l.length > 0 && l.length < 25 && !l.includes('```') && !l.includes(':'));

      setChatHistory(prev => [...prev, { 
        role: 'ai', 
        content: aiText,
        items: detectedItems.length > 3 ? detectedItems : undefined 
      }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'ai', content: '抱歉，生成内容时出了一点问题。' }]);
    } finally {
      setIsAiLoading(false);
    }
  };

  const applyAiItems = (items: string[]) => {
    const text = items.join('\n');
    setTextInput(text);
    setConfig(prev => ({ ...prev, items }));
  };

  const inputBaseClass = "w-full bg-slate-800 text-white border border-slate-700 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm transition-all placeholder-slate-500";

  return (
    <div className="flex flex-col md:flex-row h-screen overflow-hidden bg-slate-900 text-slate-100 font-sans">

      {/* 第一列：参数配置 */}
      <div className="w-full md:w-80 bg-slate-900 border-r border-slate-800 overflow-y-auto p-5 flex flex-col gap-6 shadow-xl z-20">
        <header className="mb-2">
          <h1 className="text-xl font-black text-blue-400 tracking-tight">转盘工厂</h1>
          <p className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">WHEEL DESIGNER PRO</p>
        </header>

        <section className="space-y-4">
          <h2 className="text-xs font-bold text-slate-400 uppercase tracking-widest border-b border-slate-800 pb-2">内容配置</h2>
          <textarea
            className={`${inputBaseClass} h-32 p-3 resize-none`}
            value={textInput}
            onChange={handleTextChange}
            placeholder="每行一个格子内容..."
          />
        </section>

        <section className="space-y-4">
          <h2 className="text-xs font-bold text-slate-400 uppercase tracking-widest border-b border-slate-800 pb-2">视觉风格</h2>

          <div>
            <label className="block text-xs font-semibold text-slate-500 mb-1.5">配色方案</label>
            <select
              value={config.colorScheme.name}
              onChange={(e) => {
                const scheme = COLOR_SCHEMES.find(s => s.name === e.target.value);
                if (scheme) updateConfig({ colorScheme: scheme });
              }}
              className={`${inputBaseClass} p-2.5`}
            >
              {COLOR_SCHEMES.map(s => <option key={s.name} value={s.name} className="bg-slate-900">{s.name}</option>)}
            </select>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-500 mb-1.5">边框质感</label>
            <div className="flex gap-2">
              {(['solid', 'metallic', 'glossy', 'dotted'] as BorderStyle[]).map(style => (
                <button
                  key={style}
                  onClick={() => updateConfig({ borderStyle: style })}
                  className={`flex-1 py-1 text-[10px] rounded border transition-all capitalize ${
                    config.borderStyle === style ? 'bg-blue-600 border-blue-400 text-white' : 'bg-slate-800 border-slate-700 text-slate-400'
                  }`}
                >
                  {style === 'solid' ? '平滑' : style === 'metallic' ? '金属' : style === 'glossy' ? '光泽' : '虚线'}
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-[10px] text-slate-500 mb-1">边框粗细</label>
              <input type="number" min="0" max="50" value={config.borderWidth} onChange={(e) => updateConfig({ borderWidth: Number(e.target.value) })} className={`${inputBaseClass} p-2`} />
            </div>
            <div>
              <label className="block text-[10px] text-slate-500 mb-1">轴心半径</label>
              <input type="number" min="0" max="100" value={config.hubRadius} onChange={(e) => updateConfig({ hubRadius: Number(e.target.value) })} className={`${inputBaseClass} p-2`} />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-[10px] text-slate-500 mb-1">边框颜色</label>
              <input type="color" value={config.borderColor} onChange={(e) => updateConfig({ borderColor: e.target.value })} className="w-full h-8 cursor-pointer rounded-lg border border-slate-700 bg-slate-800 p-0" />
            </div>
            <div>
              <label className="block text-[10px] text-slate-500 mb-1">轴心颜色</label>
              <input type="color" value={config.hubColor} onChange={(e) => updateConfig({ hubColor: e.target.value })} className="w-full h-8 cursor-pointer rounded-lg border border-slate-700 bg-slate-800 p-0" />
            </div>
          </div>
        </section>

        <section className="space-y-4">
          <h2 className="text-xs font-bold text-slate-400 uppercase tracking-widest border-b border-slate-800 pb-2">排版属性</h2>
          <div>
            <label className="block text-xs font-semibold text-slate-500 mb-1.5">中文字体</label>
            <select
              value={config.fontFamily}
              onChange={(e) => updateConfig({ fontFamily: e.target.value })}
              className={`${inputBaseClass} p-2.5`}
            >
              {CHINESE_FONTS.map(f => (
                <option key={f.value} value={f.value} className="bg-slate-900">{f.name}</option>
              ))}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-[10px] text-slate-500 mb-1">字号</label>
              <input type="number" min="8" max="60" value={config.fontSize} onChange={(e) => updateConfig({ fontSize: Number(e.target.value) })} className={`${inputBaseClass} p-2`} />
            </div>
            <div>
              <label className="block text-[10px] text-slate-500 mb-1">文字颜色</label>
              <input type="color" value={config.fontColor} onChange={(e) => updateConfig({ fontColor: e.target.value })} className="w-full h-8 cursor-pointer rounded-lg border border-slate-700 bg-slate-800 p-0" />
            </div>
          </div>
        </section>
      </div>

      {/* 第二列：AI 灵感对话 */}
      <div className="w-full md:w-96 bg-slate-900 border-r border-slate-800 flex flex-col h-full z-10 shadow-2xl">
        <div className="p-4 border-b border-slate-800 bg-slate-900/50 backdrop-blur-md">
          <h2 className="text-sm font-bold flex items-center gap-2 text-blue-400 uppercase tracking-tighter">
            <span className="w-2 h-2 bg-green-400 rounded-full animate-pulse shadow-[0_0_8px_rgba(74,222,128,0.8)]"></span>
            AI Assistant
          </h2>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4 scroll-smooth">
          {chatHistory.map((msg, idx) => (
            <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[92%] p-4 rounded-2xl text-xs shadow-lg transition-all border ${
                msg.role === 'user' ? 'bg-blue-600 border-blue-500 text-white rounded-tr-none' : 'bg-slate-800 border-slate-700 text-slate-200 rounded-tl-none'
              }`}>
                <div className="whitespace-pre-wrap leading-relaxed">{msg.content}</div>
                {msg.items && (
                  <button 
                    onClick={() => applyAiItems(msg.items!)}
                    className="mt-4 w-full py-2.5 px-3 bg-blue-500/10 text-blue-400 rounded-xl border border-blue-500/40 hover:bg-blue-500/20 transition-all font-black flex items-center justify-center gap-2"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                    </svg>
                    填入当前转盘
                  </button>
                )}
              </div>
            </div>
          ))}
          {isAiLoading && (
            <div className="flex justify-start">
              <div className="bg-slate-800 p-3 rounded-2xl border border-slate-700 flex gap-1.5">
                <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce"></div>
