          )}
        </div>

        <div className="p-4 bg-slate-900 border-t border-slate-800">
          <div className="flex gap-2">
            <input 
              type="text" 
              value={chatInput}
              onChange={(e) => setChatInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && callAi()}
              placeholder="我想做一个关于..."
              className={`${inputBaseClass} p-3`}
            />
            <button 
              onClick={callAi}
