    link.download = `wheel-hd-${Date.now()}.png`;
    link.href = canvasRef.current.toDataURL('image/png', 1.0);
    link.click();
  };

  const callAi = async () => {
    if (!chatInput.trim() || isAiLoading) return;
    const userMsg = chatInput;
    setChatInput('');
    setChatHistory(prev => [...prev, { role: 'user', content: userMsg }]);
    setIsAiLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `用户需求: ${userMsg}. 
        请严格根据用户要求的数量生成一套适合转盘的文案列表。
        要求：
        1. 返回一段简短的对话回复。
        2. 必须生成用户要求的【具体数量】的选项。如果用户没说数量，默认提供10个。
        3. 选项内容要有趣、适合年轻人、简洁。
        4. 列表项每行一个。不要添加编号、不要符号，只提供文字内容。`,
        config: {
          systemInstruction: "你是一个专业的创意转盘策划。你非常严谨，会严格执行用户要求的数量（Count）。你生成的内容充满活力，适合现代年轻人。"
        }
      });

      const aiText = response.text || '';
      const lines = aiText.split('\n');
      // 提取符合规则的项，过滤掉可能的对话前缀和代码块标记
      const detectedItems = lines
        .map(l => l.replace(/^[-*•\d.]+\s*/, '').trim())
        .filter(l => l.length > 0 && l.length < 30 && !l.includes('```') && !l.includes(':') && !l.includes('：'));

      setChatHistory(prev => [...prev, { 
        role: 'ai', 
        content: aiText,
        items: detectedItems.length > 0 ? detectedItems : undefined 
      }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'ai', content: '抱歉，服务繁忙，请稍后再试。' }]);
    } finally {
      setIsAiLoading(false);
    }
  };

