const App: React.FC = () => {
  const [config, setConfig] = useState<WheelConfig>(DEFAULT_CONFIG);
  const [textInput, setTextInput] = useState(DEFAULT_CONFIG.items.join('\n'));
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<{ role: 'user' | 'ai', content: string, items?: string[] }[]>([
    { role: 'ai', content: `嗨！我是你的灵感助手。请输入你想要的主题和具体的格子数量（例如：50个2026年必做清单），我会严格为你生成！` }
  ]);
  const [isAiLoading, setIsAiLoading] = useState(false);

  const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setTextInput(value);
    const items = value.split('\n').filter(line => line.trim() !== '');
    setConfig(prev => ({ ...prev, items }));
  };

  const updateConfig = (updates: Partial<WheelConfig>) => {
    setConfig(prev => ({ ...prev, ...updates }));
  };

  const downloadImage = () => {
    if (!canvasRef.current) return;
    const link = document.createElement('a');
    link.download = `wheel-ultra-hd-${APP_VERSION}-${Date.now()}.png`;
    link.href = canvasRef.current.toDataURL('image/png', 1.0);
    link.click();
  };

  const callAi = async () => {
    if (!chatInput.trim() || isAiLoading) return;
    const userMsg = chatInput;
    setChatInput('');
    setChatHistory(prev => [...prev, { role: 'user', content: userMsg }]);
    setIsAiLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `用户需求: ${userMsg}. 
        任务：严格执行生成任务。
        规则：
        1. 必须精准识别用户提到的【数量】。如果提到50个，你就必须输出50行。绝对不能偷懒、合并或省略。
        2. 返回格式：一段简短友好的回复，后面跟着每行一个选项的列表。
        3. 列表内容不要序号、不要前缀符号，直接输出文案。
        4. 风格：年轻、潮流、现代。`,
        config: {
          systemInstruction: "你是一个极其严谨且富有创意的转盘策划。你的信条是：用户要多少，我就给多少。绝对不打折扣，不缩减内容。"
        }
      });

      const aiText = response.text || '';
      const lines = aiText.split('\n');
      const detectedItems = lines
        .map(l => l.replace(/^[-*•\d.]+\s*/, '').trim())
        .filter(l => l.length > 0 && l.length < 40 && !l.includes('```') && !l.includes(':') && !l.includes('：'));

      setChatHistory(prev => [...prev, { 
        role: 'ai', 
        content: aiText,
        items: detectedItems.length > 0 ? detectedItems : undefined 
      }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'ai', content: '抱歉，大脑宕机了，请重新尝试。' }]);
    } finally {
      setIsAiLoading(false);
    }
  };

  const applyAiItems = (items: string[]) => {
    const text = items.join('\n');
    setTextInput(text);
    setConfig(prev => ({ ...prev, items }));
  };

  const inputBaseClass = "w-full bg-slate-800 text-white border border-slate-700 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm transition-all placeholder-slate-500";

  return (
    <div className="flex flex-col md:flex-row h-screen overflow-hidden bg-slate-900 text-slate-100 font-sans">

      {/* 第一列：参数配置 */}
      <div className="w-full md:w-80 bg-slate-950 border-r border-white/5 overflow-y-auto p-5 flex flex-col gap-6 shadow-2xl z-20">
        <header className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-black text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-emerald-400">转盘工厂</h1>
            <p className="text-[10px] text-slate-500 uppercase font-bold tracking-widest">Version {APP_VERSION}</p>
          </div>
        </header>

        <section className="space-y-4">
          <h2 className="text-xs font-bold text-slate-500 uppercase tracking-widest border-b border-white/5 pb-2">内容</h2>
          <textarea
            className={`${inputBaseClass} h-32 p-3 resize-none border-white/10`}
            value={textInput}
            onChange={handleTextChange}
            placeholder="每行一个内容..."
          />
        </section>

        <section className="space-y-4">
          <h2 className="text-xs font-bold text-slate-500 uppercase tracking-widest border-b border-white/5 pb-2">外观与质感</h2>

          <div>
            <label className="block text-xs font-semibold text-slate-500 mb-1.5">方案选择</label>
            <select
              value={config.colorScheme.name}
              onChange={(e) => {
                const scheme = COLOR_SCHEMES.find(s => s.name === e.target.value);
                if (scheme) updateConfig({ colorScheme: scheme });
              }}
              className={`${inputBaseClass} p-2.5 bg-slate-900`}
            >
              {COLOR_SCHEMES.map(s => <option key={s.name} value={s.name}>{s.name}</option>)}
            </select>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-500 mb-1.5">物理质感</label>
            <div className="grid grid-cols-2 gap-2">
              {[
                {id: 'solid', n: '简约'}, {id: 'metallic', n: '铝合金'}, 
                {id: 'gold', n: '流沙金'}, {id: 'chrome', n: '镭射虹'},
                {id: 'glass', n: '磨砂玻璃'}, {id: 'brushed', n: '拉丝钢'}
              ].map(style => (
                <button
                  key={style.id}
                  onClick={() => updateConfig({ borderStyle: style.id as BorderStyle })}
                  className={`py-2 text-[10px] rounded-lg border transition-all ${
                    config.borderStyle === style.id ? 'bg-blue-600 border-blue-400 font-bold' : 'bg-slate-900 border-white/5 text-slate-500'
                  }`}
                >
                  {style.n}
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-[10px] text-slate-500 mb-1">边框宽度</label>
              <input type="number" min="0" max="80" value={config.borderWidth} onChange={(e) => updateConfig({ borderWidth: Number(e.target.value) })} className={`${inputBaseClass} p-2`} />
            </div>
            <div>
              <label className="block text-[10px] text-slate-500 mb-1">轴心</label>
              <input type="number" min="0" max="150" value={config.hubRadius} onChange={(e) => updateConfig({ hubRadius: Number(e.target.value) })} className={`${inputBaseClass} p-2`} />
            </div>
          </div>
        </section>

        <section className="space-y-4">
          <h2 className="text-xs font-bold text-slate-500 uppercase tracking-widest border-b border-white/5 pb-2">排版</h2>
          <div>
            <label className="block text-xs font-semibold text-slate-500 mb-1.5">潮流字体</label>
            <select
              value={config.fontFamily}
              onChange={(e) => updateConfig({ fontFamily: e.target.value })}
              className={`${inputBaseClass} p-2.5 bg-slate-900`}
            >
              {CHINESE_FONTS.map(f => <option key={f.value} value={f.value}>{f.name}</option>)}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-3 pb-6">
            <div>
              <label className="block text-[10px] text-slate-500 mb-1">大小</label>
              <input type="number" min="8" max="80" value={config.fontSize} onChange={(e) => updateConfig({ fontSize: Number(e.target.value) })} className={`${inputBaseClass} p-2`} />
            </div>
            <div>
              <label className="block text-[10px] text-slate-500 mb-1">色彩</label>
              <input type="color" value={config.fontColor} onChange={(e) => updateConfig({ fontColor: e.target.value })} className="w-full h-8 cursor-pointer rounded-lg border border-white/10 bg-slate-900 p-0" />
            </div>
          </div>
        </section>
      </div>

      {/* 第二列：AI 对话 */}
      <div className="w-full md:w-96 bg-slate-900 border-r border-white/5 flex flex-col h-full z-10">
        <div className="p-4 border-b border-white/5 bg-slate-900/80 backdrop-blur-lg flex items-center justify-between">
          <h2 className="text-sm font-bold flex items-center gap-2 text-blue-400">
            <span className="w-2 h-2 bg-emerald-400 rounded-full animate-ping"></span>
            灵感实验室
          </h2>
          <span className="text-[9px] bg-blue-500/20 text-blue-400 px-2 py-0.5 rounded-full font-bold">SMART GENERATE</span>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4 scroll-smooth scrollbar-hide">
          {chatHistory.map((msg, idx) => (
            <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[95%] p-4 rounded-2xl text-xs shadow-2xl transition-all border ${
                msg.role === 'user' ? 'bg-blue-600 border-white/10 text-white rounded-tr-none' : 'bg-slate-800 border-white/5 text-slate-200 rounded-tl-none'
              }`}>
                <div className="whitespace-pre-wrap leading-relaxed opacity-90">{msg.content}</div>
                {msg.items && (
                  <button 
                    onClick={() => applyAiItems(msg.items!)}
                    className="mt-4 w-full py-3 px-3 bg-white/10 hover:bg-white/20 text-white rounded-xl border border-white/10 transition-all font-black flex items-center justify-center gap-2"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                    </svg>
                    立即填入 {msg.items.length} 个格子
                  </button>
                )}
              </div>
            </div>
          ))}
          {isAiLoading && (
            <div className="flex justify-start">
              <div className="bg-slate-800 p-3 rounded-2xl border border-white/5 flex gap-2">
                <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce"></div>
                <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce [animation-delay:0.1s]"></div>
                <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
              </div>
            </div>
          )}
        </div>

        <div className="p-4 bg-slate-950 border-t border-white/5">
          <div className="flex gap-2">
            <input 
              type="text" 
              value={chatInput}
              onChange={(e) => setChatInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && callAi()}
              placeholder="例：50个年轻人的心愿清单..."
              className={`${inputBaseClass} p-4 bg-slate-900 border-white/5`}
            />
            <button 
              onClick={callAi}
              disabled={isAiLoading}
              className="px-6 py-4 bg-blue-600 hover:bg-blue-500 text-white rounded-xl text-sm font-black transition-all shadow-xl shadow-blue-900/20 disabled:opacity-50"
            >
              生成
            </button>
          </div>
        </div>
      </div>

      {/* 第三列：预览与下载 (优化下载按钮位置到顶部) */}
      <main className="flex-1 flex flex-col bg-[#010203] relative">
        <div className="absolute inset-0 opacity-10 pointer-events-none" style={{ backgroundImage: 'radial-gradient(#fff 0.5px, transparent 0.5px)', backgroundSize: '30px 30px' }} />

        {/* 下载条移至顶部 */}
        <div className="w-full p-5 bg-slate-950/80 backdrop-blur-3xl border-b border-white/5 flex items-center justify-between z-30 shadow-2xl">
          <div>
            <h3 className="text-sm font-black text-white uppercase tracking-tighter">Ultra HD Production</h3>
            <p className="text-[10px] text-slate-500 font-bold mt-0.5">3200 PX • TRANSPARENT • SUPERSAMPLED</p>
          </div>

          <button
            onClick={downloadImage}
            className="group py-3.5 px-12 bg-white text-black font-black rounded-2xl shadow-white/10 shadow-2xl transition-all transform hover:-translate-y-1 active:scale-95 flex items-center gap-3"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 group-hover:scale-110 transition-transform" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
            </svg>
            下载高清 PNG
          </button>
        </div>

        {/* 核心画布区域 - 响应式且无遮挡 */}
        <div className="flex-1 relative flex items-center justify-center p-4 sm:p-12 overflow-hidden">
          <div className="w-full h-full max-w-[80%] max-h-[80%] aspect-square relative flex items-center justify-center">
            <WheelCanvas 
              config={config} 
              exportScale={4} 
              onCanvasReady={(canvas) => { canvasRef.current = canvas; }} 
            />
          </div>
        </div>

        {/* 底部微型水印/装饰 */}
        <div className="p-3 text-center text-[8px] text-slate-700 font-bold uppercase tracking-[0.5em] select-none">
          AI-POWERED RENDERING ENGINE • QUANTUM ACCELERATED
        </div>
      </main>
    </div>
  );
};

export default App;
